UPDATE `quest_template_locale` SET `QuestDescription`='No habríamos sobrevivido a Tanaan sin tu fuerza, $n. Muchos draenei y miembros de la Alianza están en deuda contigo.$B$BAntes de que partiéramos hacia el Portal Oscuro, el rey Wrynn recomendó personalmente que te pusiera al cargo de nuestras operaciones aquí, en Draenor. Tras haberte visto en acción, no puedo sino estar de acuerdo.$B$BDebes fundar esta ciudadela. Coloca el estandarte y comenzaremos de inmediato con la construcción, Comandante.', `QuestCompletionLog`='', `VerifiedBuild`=25549 WHERE (`ID`=34583 AND `locale`='esES');
