UPDATE `quest_template_locale` SET `QuestDescription`='Desde que la Horda obtuvo la Campana Divina llevo buscando una forma de contrarrestar su poder.$b$bMi investigación me ha llevado hasta esta tumba. Voy a entrar. Sígueme y te contaré el resto mientras nos adentramos.$b$bSi nos separamos, reúnete conmigo en la entrada de la tumba. Avísame cuando quieras avanzar.', `PortraitGiverText`='A veces solo una leyenda puede derrotar a otra leyenda.', `QuestCompletionLog`='', `VerifiedBuild`=25549 WHERE (`ID`=32321 AND `locale`='esES');
