UPDATE `quest_template_locale` SET `LogDescription`='Habla con lord Taran Zhu en el Frente Gao-Ran en las Estepas de Tong Long.', `QuestDescription`='Con tu ayuda, hemos disipado a los espíritus de este lugar.$B$BPor fin, podrán descansar en paz.$B$BSin embargo, me temo que nuestro viaje por esta tierra maldita no ha hecho más que comenzar.$B$BTengo importantes asuntos que terminar aquí, pero partiremos pronto.$B$BNecesito que alguien se adelante y le diga a lord Taran Zhu que nos uniremos a él.$B$BBúscale en el Frente Gao-Ran. Háblale de lo que habitaba aquí.', `VerifiedBuild`=25549 WHERE (`ID`=30785 AND `locale`='esES');
