UPDATE `quest_template_locale` SET `LogDescription`='Preséntate ante el alto señor supremo Colmillosauro en el Fuerte Grommash, en Orgrimmar.', `QuestDescription`='Por la presente se ordena a todos los miembros aptos de la Horda que se presenten ante el alto señor supremo Colmillosauro en el Fuerte Grommash.$b$bNecesita tu ayuda para preparar el glorioso ataque contra las Tierras Altas Crepusculares y contra nuestros dos enemigos: la Alianza y el Martillo Crepuscular.$b$bReúnete con él en el Fuerte Grommash, en el centro del Valle de la Fuerza, en Orgrimmar.$b$b¡El destino te llama!', `VerifiedBuild`=25549 WHERE (`ID`=28717 AND `locale`='esES');
UPDATE `quest_template_locale` SET `LogDescription`='Habla con el rey Anduin Wrynn en el Castillo de Ventormenta, en Ventormenta.', `QuestDescription`='Por orden de su alteza real, el rey Anduin Wrynn, todos los ciudadanos capaces de la Alianza deben presentarse en la Sala del Trono, en el Castillo de Ventormenta.$b$bEl rey Wrynn necesita un héroe digno de confianza y que haya demostrado su valía para una misión de la mayor importancia.$b$bEl Castillo de Ventormenta está situado en la zona este de la Ciudad de Ventormenta.$b$b¡Por la gloria y el honor de la Alianza!', `VerifiedBuild`=25549 WHERE (`ID`=28716 AND `locale`='esES');
UPDATE `quest_template_locale` SET `QuestDescription`='¡Malditos grells! Han vuelto a robar de nuestras despensas.$b$bSi no te importa echarme una mano, seguro que tienen las bolsas que me han robado en sus campamentos al oeste. Te recompensaré si me las traes de vuelta.', `QuestCompletionLog`='', `VerifiedBuild`=25549 WHERE (`ID`=28715 AND `locale`='esES');
