UPDATE `quest_template_locale` SET `QuestDescription`='Por la presente se ordena a todos los miembros aptos de la Horda que se presenten ante el teniente general Orion en los Peldaños del Destino.$b$bTus habilidades son necesarias para combatir la presencia de la Legión Ardiente en lo que queda de Terrallende.$b$bVe al Circo de las Sombras en Orgrimmar y usa el portal que hay cerca del vendedor de suministros de venenos para llegar a la Península del Fuego Infernal.$b$b¡El destino te reclama!', `VerifiedBuild`=25549 WHERE (`ID`=28705 AND `locale`='esES');
