UPDATE `quest_template_locale` SET `QuestDescription`='El rey Anduin Wrynn ha solicitado que todos los aventureros aptos se dirijan a las Profundidades de Roca Negra, al noroeste de la Vigilia de Morgan, ¡de inmediato!$b$b¡Los enanos Hierro Negro suponen una grave amenaza para los ciudadanos de Crestagrana! Si decides ayudar, dirígete a las Profundidades de Roca Negra y habla con Morgan, quien acaba de volver de su larga ausencia y desea ejecutar su venganza contra la nación Hierro Negro.', `VerifiedBuild`=25549 WHERE (`ID`=28068 AND `locale`='esES');
