UPDATE `quest_template_locale` SET `QuestDescription`='Vale, cierra el pico y déjame hablar porque el plan es este.$b$bEs probable que esos gnolls y los múrlocs se encuentren ahí fuera, en alguna parte. Así que coge mi astuto disfraz y póntelo para parecer una planta. Te escabulles entre ellos y lanzas estas feromonas que recogiste a los Pellejomusgo que estén con los múrlocs.$b$bEntonces los múrlocs se volverán locos, ¡y los Pellejomusgo se lo pensarán dos veces antes de trabajar con unos bichos tan tarados!', `QuestCompletionLog`='', `VerifiedBuild`=25549 WHERE (`ID`=26868 AND `locale`='esES');
