UPDATE `quest_template_locale` SET `LogDescription`='Obtén 6 juncos akiris de los expedicionarios nagas.', `QuestDescription`='Los expedicionarios nagas que están al sur de aquí llevan un valioso junco del océano, los juncos akiris. Los mercaderes los usan para preparar medicinas y cataplasmas. Los artesanos los usan para forrar armaduras ¡e incluso para liar cigarros!$b$bPor las tardes, cuando se acababa el trabajo, padre me enseñaba como usarlos... pero, por desgracia, se nos acabaron. ¿Te importaría traernos más?', `QuestCompletionLog`='', `VerifiedBuild`=25549 WHERE (`ID`=26819 AND `locale`='esES');
