UPDATE `quest_template_locale` SET `LogTitle`='Colmillosauro estará complacido', `LogDescription`='Usa el portal en el Puerto Faucedraco para ir a Orgrimmar y preséntate ante el alto señor supremo Colmillosauro.', `QuestDescription`='¡El portal está listo!$b$bNo es lo bastante poderoso como para transportar un ejército, pero podemos mantener la conexión el tiempo suficiente para permitir que individuos importantes pasen de un lado a otro.$b$bColmillosauro querrá saber de los progresos que hemos hecho aquí. Cruza el portal hacia Orgrimmar y dale la noticia.', `QuestCompletionLog`='Preséntate ante: Alto señor supremo Colmillosauro. Zona: Portal en el Puerto Faucedraco para ir a Orgrimmar.', `VerifiedBuild`=25549 WHERE (`ID`=26798 AND `locale`='esES');
