UPDATE `quest_template_locale` SET `LogTitle`='Salvar al supervisor Olento', `LogDescription`='Usa el orbe de control de ettin para controlar a un ettin y después usa el orbe de control de ettin con tu ettin de cañón subyugado para que levante el pedrusco gigante que aplasta al supervisor Olento en Villa del Lago.', `QuestDescription`='<Al tocar el orbe, escuchas un ligero clic.>$B$B<Coges el orbe del pedestal.>$b$b<Ahora controlas el orbe, y por lo tanto controlas a los ettins. Tal vez puedas usar a uno de ellos para levantar el enorme pedrusco que está aplastando al supervisor Olento en Villa del Lago. Encuentra a un ettin y usa el orbe en él. Después dirígete a Villa del Lago.>', `PortraitGiverText`='Ettins de cañón: Feos y malos.', `QuestCompletionLog`='', `VerifiedBuild`=25549 WHERE (`ID`=26520 AND `locale`='esES');
