UPDATE `quest_template_locale` SET `LogTitle`='La leyenda del capitán Grayson', `LogDescription`='Encuentra al capitán Grayson en el Faro de Poniente, en los Páramos de Poniente.', `QuestDescription`='¿Alguna vez has oído hablar del capitán Grayson? Hay quien dice que solo es un producto de la imaginación de un marinero borracho, ¡pero todos los habitantes de los Páramos de Poniente saben que existe! Es un fantasma que habita en el Faro de Poniente, enfrenta de la Playa Larga.$b$b¿Te atreves a investigar?', `VerifiedBuild`=25549 WHERE (`ID`=26371 AND `locale`='esES');
UPDATE `quest_template_locale` SET `LogTitle`='De vuelta a Colina del Centinela', `LogDescription`='Preséntate ante el alguacil Gryan Mantorrecio en Colina del Centinela, en los Páramos de Poniente.', `QuestDescription`='No conviene tomarse a la Hermandad Defias a la ligera, $n. Lo que acabas de presenciar es el nacimiento de una organización de criminales despiadados que no se detendrán ante nada para reducir Ventormenta a cenizas.$b$bQuiero que vuelvas a Colina del Centinela y le digas a Gryan que le enviaré tropas. Espero que no sea demasiado tarde.', `VerifiedBuild`=25549 WHERE (`ID`=26370 AND `locale`='esES');
