UPDATE `quest_template_locale` SET `LogDescription`='Usa el incienso de heraldo delante del huevo de Aviana en el Santuario de Aviana.', `QuestDescription`='No me cabe duda de que TÚ eres $gel mensajero:la mensajera; de Aviana, $n. Fuiste tú $gel primero:laprimera; en verla y en rescatar su esencia de las garras de un dragón.$b$bSí, creo que Aviana renacerá en nuestro mundo. Y tú tendrás el honor de acompañarla a través del umbral.$b$bCoge este incienso y quémalo delante del huevo de Aviana en la sala que está justo encima de mí.$b$bEl ancestro espera, $n. ¡Nuestra liberación ha llegado!', `QuestCompletionLog`='', `VerifiedBuild`=25549 WHERE (`ID`=25807 AND `locale`='esES');
