UPDATE `quest_template_locale` SET `LogTitle`='Mensaje para Colmillosauro', `LogDescription`='Entrega el emblema IV:7 al alto señor supremo Colmillosauro en el Fuerte Grommash, en Orgrimmar.', `QuestDescription`='<La leal Lanza Negra abre el paquete y lee la carta de dentro. Al finalizar la nota de Thrall, un atisbo de sonrisa se dibuja en su rostro.>$b$bDeberíah llevarl''ehto directamente a Colmillosauro, en Orgrimmar. Asegúrate de que sepa qu''el paquet''eh de Thrall.$b$bCoge mi raptor. ¡Date prisa, $gpequeño:pequeña;, no hay tiempo que perder!', `VerifiedBuild`=25549 WHERE (`ID`=25267 AND `locale`='esES');
