UPDATE `quest_template_locale` SET `LogDescription`='Mata a lord Tuétano.$b$bEsta misión se puede completar con cualquier tamaño de banda en cualquier modo de dificultad.', `QuestDescription`='Lord Tuétano es el guardián del Trono Helado en la cámara de La Aguja. El Rey Exánime lo construyó a partir de los huesos de miles de aventureros derrotados y maneja el poder del mismísimo trono.$b$bSi no destruimos a este esqueleto no podremos tomar la Ciudadela de la Corona de Hielo.$b$b¡El Consejo de los Seis ha decretado que lord Tuétano debe morir!', `QuestCompletionLog`='', `VerifiedBuild`=25549 WHERE (`ID`=24590 AND `locale`='esES');
UPDATE `quest_template_locale` SET `LogDescription`='Mata a lord Jaraxxus.$b$bEsta misión se puede completar con cualquier tamaño de banda en cualquier modo de dificultad.', `QuestDescription`='El archimago Tiemporeja ha previsto un suceso terrible que está a punto de ocurrir. Un insensato brujo gnomo está a punto de invocar accidentalmente a un señor eredar de la Legión Ardiente en mitad de la Prueba del Cruzado.$b$bDebes estar presente cuando ocurra, $c. Si lord Jaraxxus escapa, abrirá un portal y la Legión Ardiente volverá a invadir nuestro mundo.$b$b¡El Consejo de los Seis ha decretado que lord Jaraxxus debe morir!', `QuestCompletionLog`='', `VerifiedBuild`=25549 WHERE (`ID`=24589 AND `locale`='esES');
UPDATE `quest_template_locale` SET `QuestCompletionLog`='', `VerifiedBuild`=25549 WHERE (`ID`=24588 AND `locale`='esES');
