UPDATE `quest_template_locale` SET `LogDescription`='Reúnete con Lok''lira la vieja bruja en el Poblado Brunnhildar.', `QuestDescription`='Excelente. En el extremo este de la mina hay una salida que lleva al Poblado Brunnhildar. Síguela y te veré allí.$B$BNo deben vernos juntos, para que nadie sospeche que me estás ayudando. Usaré mi magia para disfrazar mi apariencia. No te preocupes, $r, encontraremos a tu amigo enseguida.', `VerifiedBuild`=25549 WHERE (`ID`=12921 AND `locale`='esES');
