UPDATE `quest_template_locale` SET `LogTitle`='Informa a lord Afrasastrasz', `LogDescription`='Habla con lord Afrasastrasz en el Templo del Reposo del Dragón.', `QuestDescription`='Aborrezco la muerte... Cualquier muerte. ¡Pero no me quedaré de brazos cruzados mientras Malygos nos mata y profana el templo!$b$bHe asignado a lord Afrasastrasz como comandante para la defensa de Reposo del Dragón.$b$bHabla con Torastrasza para ir en draco hasta él.$b$bPréstale tu ayuda, $n. Tu participación en la defensa de Reposo del Dragón será crítica para que prevalezcamos frente al Vuelo Azul.', `VerifiedBuild`=25549 WHERE (`ID`=12435 AND `locale`='esES');
