UPDATE `quest_template_locale` SET `QuestDescription`='Los arakkoa han vuelto a atacarnos, esta vez, en medio de la noche y utilizando su magia oscura para escapar antes de que pudiéramos organizar a nuestros soldados. $B$BVelo Reskk y Velo Shienor quedan al norte y al noroeste. Encuentra esos nidos de arakkoa y mata a todos los que puedas. Quizás no nos teman, pero al menos reduciremos su número.', `QuestCompletionLog`='', `VerifiedBuild`=25549 WHERE (`ID`=10869 AND `locale`='esES');
