UPDATE `quest_template_locale` SET `QuestDescription`='Necesito examinar las crías que están criando en el Aquelarre Alanegra.$B$BDebería haber muchos volando por su base llena de cavernas, así como varios huevos; si te acercas a ellos, probablemente se romperán.$B$BPor favor, $n, coge la red y tráeme algunos que estén vivos.$B$BPuedes encontrarlos dirigiéndote al oeste a través del Puente Calavermis y después pasando el Túnel Calavermis. Sigue el camino hasta que llegues al final pasando Grishnath y el Bosque del Cuervo.', `QuestCompletionLog`='', `VerifiedBuild`=25549 WHERE (`ID`=10747 AND `locale`='esES');
