UPDATE `quest_template_locale` SET `LogDescription`='La exarca Onaala del Altar de Sha''tar quiere que consigas 8 gujas de Furia del Sol de los suplicantes cazadores de demonios y de los iniciados cazadores de demonios que se encuentran en las Ruinas de Karabor, al sureste del Altar de Sha''tar.$B$BCompletar misiones para los Aldor hará que disminuya tu nivel de reputación con los Arúspices.', `QuestCompletionLog`='', `VerifiedBuild`=25549 WHERE (`ID`=10587 AND `locale`='esES');
