UPDATE `quest_template_locale` SET `LogDescription`='Ve al Barrio Real, en Entrañas, y entrégale el collar de Sylvanas a lady Sylvanas Brisaveloz.', `QuestDescription`='¡Qué extraordinario! Parece ser un regalo para lady Sylvanas Brisaveloz de su hermana, Alleria.$B$BDebes llevárselo a Entrañas rápidamente. lady Sylvanas está en el Barrio Real.$B$BPara llegar allí, utiliza el orbe de traslado que está en el Sagrario Interior de la Aguja Furia del Sol, en la Ciudad de Lunargenta para cruzar a Entrañas. Cuando llegues, utiliza el elevador hasta la ciudad. Usa tus mapas si necesitas orientación para encontrar el Barrio Real.', `VerifiedBuild`=25549 WHERE (`ID`=9180 AND `locale`='esES');
UPDATE `quest_template_locale` SET `LogDescription`='Ve al Barrio Real, en Entrañas, y entrégale el collar de Sylvanas a lady Sylvanas Brisaveloz.', `QuestDescription`='¡Qué extraordinario! Parece ser un regalo para lady Sylvanas Brisaveloz de su hermana, Alleria.$B$BDebes llevárselo a Entrañas rápidamente. lady Sylvanas está en el Barrio Real.$B$BPara llegar allí, utiliza el orbe de traslado que está en el Sagrario Interior de la Aguja Furia del Sol, en la Ciudad de Lunargenta para cruzar a Entrañas. Cuando llegues, utiliza el elevador hasta la ciudad. Usa tus mapas si necesitas orientación para encontrar el Barrio Real.', `VerifiedBuild`=25549 WHERE (`ID`=9177 AND `locale`='esES');
