UPDATE `quest_template_locale` SET `VerifiedBuild`=25549 WHERE (`ID`=477 AND `locale`='esES');
UPDATE `quest_template_locale` SET `LogTitle`='Corrupción Tuercepinos', `VerifiedBuild`=25549 WHERE (`ID`=476 AND `locale`='esES');
UPDATE `quest_template_locale` SET `QuestDescription`='Se avecinan problemas en el bosque.$B$BGaerolas Talvethren es el Gran Celador de los druidas hibernantes de la Garra en Túmulo de Ban''ethil. Su función como protector de los Adormecidos es preservar su seguridad de modo que no se rompa el pacto que tienen con Ysera. $b$bPero hace tiempo que no sé nada de él y me inquieta. Viaja al este hasta la Aldea Brisa Estelar para hablar con Gaerolas y regresa para informarme de todo. Cuando sepa que mis hermanos duermen apaciblemente, me quedaré más tranquilo.', `VerifiedBuild`=25549 WHERE (`ID`=475 AND `locale`='esES');
